  if (f === 'both') { const W = rand(8, 40); const H = rand(6, 30); const k = rand(2, 3); return kp({ key: `ar:bo:${W}:${H}:${k}`, topic, story: st(mode, '🏊', 'Pool Cover'), prompt: `A rectangular pool is ${W} m by ${H} m. A bigger pool has the same width but its length is ${k} times as long (${W} m becomes ${W * k} m). What is the area of the bigger pool in square meters?`, answer: W * k * H, hints: [`The new length is ${W} × ${k} = ${W * k} m.`], explanation: `${W} × ${k} = ${W * k}. ${W * k} × ${H} = ${fmt(W * k * H)} square meters.` }); }
  if (f === 'compare') { const a = [rand(8, 30), rand(6, 24)]; const b = [rand(8, 30), rand(6, 24)]; if (a[0] * a[1] === b[0] * b[1]) return area(mode, d); return kp({ key: `ar:cm:${a.join('x')}:${b.join('x')}`, topic, prompt: `Garden A is ${a[0]} m by ${a[1]} m. Garden B is ${b[0]} m by ${b[1]} m. How many more square meters is the bigger garden?`, answer: Math.abs(a[0] * a[1] - b[0] * b[1]), hints: ['Find each area, then subtract.'], explanation: `${a[0]} × ${a[1]} = ${a[0] * a[1]} and ${b[0]} × ${b[1]} = ${b[0] * b[1]}. The difference is ${Math.abs(a[0] * a[1] - b[0] * b[1])}.` }); }
  if (f === 'cost') { const W = rand(8, 30); const H = rand(6, 20); const p = rand(2, 9); return kp({ key: `ar:cs:${W}:${H}:${p}`, topic, story: st(mode, '🧱', 'New Carpet'), prompt: `${nm()} wants carpet for a room ${W} feet by ${H} feet. Carpet costs $${p} per square foot. How much will it cost, in dollars?`, answer: W * H * p, hints: ['Find the area first, then multiply by the price.'], explanation: `${W} × ${H} = ${W * H} square feet. ${W * H} × $${p} = $${fmt(W * H * p)}.` }); }
