    if (f === 'ribbon') { const m = rand(2, 9); const cm = rand(1, 9) * 10; return kp({ key: `me:s:rb:${m}:${cm}`, topic, story: st(mode, '🎀', 'Ribbon'), prompt: `${x} has a ribbon that is ${m} meters ${cm} centimeters long. How long is it in centimeters?`, answer: m * 100 + cm, hints: ['1 meter = 100 centimeters.'], explanation: `${m} × 100 = ${m * 100}. ${m * 100} + ${cm} = ${m * 100 + cm} cm.` }); }
